481	        } else {
482	            // 召回先提交：拆分被拦截 422，子批停留 RELEASED 但不可用，无新子批
483	            assertEquals(422, split);
484	            assertEquals("RELEASED", currentStatus(child));
485	            assertEquals(0, jdbc.queryForObject(
486	                    "SELECT COUNT(*) FROM batch WHERE batch_key IN (?, ?)", Integer.class, g1, g2));
487	        }
