569	    public StoredResponse rework(String originBatchKey, ReworkRequest req) {
570	        String fingerprint = fingerprint("rework", originBatchKey, req.reworkKey(),
571	                req.reworkBatchKey(), req.reworkReason());
572	        return executeIdempotent(CMD_REWORK, req.commandKey(), fingerprint, () -> {
573	            BatchRepository.BatchRow origin = repo.findBatchForUpdate(originBatchKey)
574	                    .orElseThrow(() -> ApiException.notFound("批次不存在: " + originBatchKey));
575	            // 原批行锁后重查命令快照：并发同键请求在锁等待期间可能已由对方提交
576	            var logged = loggedResponse(CMD_REWORK, req.commandKey(), fingerprint);
577	            if (logged.isPresent()) {
578	                return logged.get();
579	            }
580	            // 同一批次只能返工一次：已存在返工登记时按 reworkKey 幂等回放或 409
581	            var existingRework = repo.findReworkByOrigin(originBatchKey);
582	            if (existingRework.isPresent()) {
583	                return replayOrConflict(existingRework.get(), req);
