588	                        + " 不允许返工，仅 REJECTED（不合格未放行）批次可返工");
589	            }
590	            assertNoRecalledAncestor(originBatchKey);
591	            List<String> required = repo.findRequiredTests(originBatchKey);
592	            Set<String> testedItems = new HashSet<>();
593	            for (BatchRepository.TestRow t : repo.findTests(originBatchKey)) {
594	                testedItems.add(t.testItem());
595	            }
596	            if (!testedItems.containsAll(required)) {
597	                throw ApiException.unprocessable("必做检验未全部完成，不能返工");
598	            }
599	            if (origin.generation() >= MAX_GENERATION) {
600	                throw ApiException.unprocessable("单条血缘链累计返工代次上限为 " + MAX_GENERATION
601	                        + "，当前代次为 " + origin.generation() + "，不可继续返工");
602	            }
603	            if (repo.findBatch(req.reworkBatchKey()).isPresent()) {
604	                throw ApiException.conflict("返工批次 batchKey 已存在: " + req.reworkBatchKey());
605	            }
