614	                    origin.batchNo(), origin.producedAt(), BatchStatus.QUARANTINED.name(),
615	                    newGeneration, now));
616	            for (int i = 0; i < required.size(); i++) {
617	                repo.insertRequiredTest(req.reworkBatchKey(), required.get(i), i + 1);
618	            }
619	            // 原批次登记为唯一父批（REWORK 边）；每个返工批次仅一条入边
620	            repo.insertLineage(new BatchRepository.LineageRow(0L, originBatchKey,
621	                    req.reworkBatchKey(), EDGE_REWORK, 1, now));
622	            repo.insertRework(new BatchRepository.ReworkRow(0L, req.reworkKey(), originBatchKey,
623	                    req.reworkBatchKey(), req.reworkReason(), newGeneration, now));
624	            repo.updateStatus(originBatchKey, BatchStatus.REWORKED.name());
625	
626	            ReworkResponse body = new ReworkResponse(
627	                    req.reworkKey(), originBatchKey, BatchStatus.REWORKED,
628	                    new ReworkResponse.ReworkBatch(req.reworkBatchKey(), origin.batchNo(),
629	                            origin.productCode(), Instant.parse(origin.producedAt()),
630	                            BatchStatus.QUARANTINED, newGeneration, required, Instant.parse(now)),
631	                    req.reworkReason(), Instant.parse(now));
